/**
 * Song catalog contract.
 *
 * A song is data, never markup: gameplay reads `lines[]` only. The shipped
 * catalog is generated by `scripts/music/build_song_assets.py` from the same
 * source that renders the audio, so a line boundary can never disagree with
 * the music it belongs to.
 */

import rawCatalog from '../../../../shared/music/songCatalog.json';
import { AUDIO_SOURCE_TYPE, RANKED_SAFE_SOURCES } from './audioAdapter.js';

export const DIFFICULTY_LABELS = Object.freeze({
  EASY: 'DỄ',
  MEDIUM: 'TRUNG BÌNH',
  HARD: 'KHÓ',
  EXPERT: 'SIÊU NHANH',
});

export const DIFFICULTY_ORDER = Object.freeze({ EASY: 0, MEDIUM: 1, HARD: 2, EXPERT: 3 });

const asInt = (value, fallback = 0) => (Number.isFinite(Number(value)) ? Math.round(Number(value)) : fallback);

/** Structural validation — the same rules the server enforces before publish. */
export function validateSong(song) {
  const errors = [];
  if (!song || typeof song !== 'object') return ['Bài hát không hợp lệ'];
  if (!song.id) errors.push('Thiếu id bài hát');
  if (!song.title) errors.push('Thiếu tên bài hát');
  if (!song.audioSource?.url) errors.push('Thiếu audio');
  if (song.audioSource && !Object.values(AUDIO_SOURCE_TYPE).includes(song.audioSource.type)) {
    errors.push('Nguồn audio không được hỗ trợ');
  }
  if (!song.audioSource?.licence) errors.push('Thiếu metadata bản quyền audio');
  if (!song.lyricsSource?.rightsStatus) errors.push('Thiếu metadata bản quyền lời bài hát');
  if (!Array.isArray(song.lines) || song.lines.length === 0) {
    errors.push('Bài hát chưa có câu hát');
    return errors;
  }
  if (song.lines.some((line) => !String(line.text || '').trim())) errors.push('Có câu hát rỗng');
  let previousEnd = -1;
  song.lines.forEach((line, index) => {
    const start = Number(line.startMs);
    const end = Number(line.endMs);
    if (!Number.isFinite(start) || !Number.isFinite(end)) {
      errors.push(`Câu ${index + 1} thiếu mốc thời gian`);
      return;
    }
    if (end <= start) errors.push(`Câu ${index + 1} có thời lượng không hợp lệ`);
    if (start < previousEnd - 1) errors.push(`Câu ${index + 1} chồng lên câu trước`);
    previousEnd = end;
  });
  if (Number(song.durationMs) > 0 && previousEnd > Number(song.durationMs) + 500) {
    errors.push('Câu hát vượt quá thời lượng bài');
  }
  return errors;
}

export function normalizeSong(song) {
  const lines = [...(song.lines || [])]
    .map((line, index) => ({
      id: line.id || `l${index + 1}`,
      index,
      startMs: asInt(line.startMs),
      endMs: asInt(line.endMs),
      text: String(line.text ?? '').normalize('NFC'),
    }))
    .sort((a, b) => a.startMs - b.startMs);

  const metrics = song.metrics || {};
  return {
    ...song,
    difficulty: DIFFICULTY_LABELS[song.difficulty] ? song.difficulty : 'MEDIUM',
    difficultyLabel: DIFFICULTY_LABELS[song.difficulty] || 'TRUNG BÌNH',
    durationMs: asInt(song.durationMs),
    timedLyricsVersion: asInt(song.timedLyricsVersion, 1),
    lines,
    totalChars: asInt(metrics.charCount, lines.reduce((sum, line) => sum + line.text.length, 0)),
    charsPerSecond: Number(metrics.charsPerSecond) || 0,
    rankedSafe: RANKED_SAFE_SOURCES.includes(song.audioSource?.type),
  };
}

export const MUSIC_SONGS = Object.freeze(
  (rawCatalog.songs || []).map(normalizeSong).filter((song) => validateSong(song).length === 0),
);

export const MUSIC_CATALOG_META = Object.freeze({
  version: rawCatalog.version,
  generatedAt: rawCatalog.generatedAt,
  licence: rawCatalog.licence,
  count: MUSIC_SONGS.length,
});

export function songById(id) {
  return MUSIC_SONGS.find((song) => song.id === String(id)) || null;
}

/** Search only what the player can see: title, artist, mood. */
export function searchSongs(query, songs = MUSIC_SONGS) {
  const needle = String(query || '').trim().toLowerCase();
  if (!needle) return songs;
  return songs.filter((song) => [song.title, song.artist, song.mood, song.difficultyLabel]
    .filter(Boolean)
    .some((field) => String(field).toLowerCase().includes(needle)));
}

/** "Độ khó không chỉ là BPM": density + accents + phrase length decide the label. */
export function describeDifficulty(song) {
  const cps = Number(song?.charsPerSecond) || 0;
  const accent = Number(song?.metrics?.accentRatio) || 0;
  const density = cps >= 5 ? 'dày' : cps >= 4 ? 'vừa' : 'thoáng';
  const accents = accent >= 0.3 ? 'nhiều dấu' : 'ít dấu';
  return `${song?.difficultyLabel || 'TRUNG BÌNH'} · ${density} · ${accents}`;
}

/** Total sung characters — used for progress rails and server cross-checks. */
export function totalLyricChars(song) {
  return (song?.lines || []).reduce((sum, line) => sum + String(line.text || '').length, 0);
}

/** The full lyric text, exactly as the server reconstructs it for validation. */
export function lyricText(song) {
  return (song?.lines || []).map((line) => String(line.text || '').normalize('NFC')).join('\n');
}
